const { BrowserWindow, app, ipcMain } = require("electron/main")
// Use the hardened axios instance — adds HMAC + nonce + timestamp + signature
// headers on every request so the backend's apiSecretMiddleware accepts them.
const axios = require("./axiosConfig")
const fs = require("fs")
const fsx = require("fs-extra")
const archiver = require("archiver")
const FormData = require("form-data")
const path = require("path")
const { spawn } = require("child_process")
const { pipeline } = require("stream")
const { promisify } = require("util")
const puppeteerCore = require("puppeteer-core")
const { dialog } = require("electron")
const crypto = require("crypto")
const os = require("os")
const net = require("net")
// All backend URLs come from the single shared config — see config.js for
// why this was extracted. Editing the prefix here used to require also
// editing main.js + the renderer's .env.production; now you edit once.
const { BROWSER_API_URL } = require("./config")
const { withNetworkRetry } = require("./withNetworkRetry")

// Kept as `API_URL` for compatibility with the existing call sites.
const API_URL = BROWSER_API_URL

// Reasonable defaults for streaming downloads / regular POSTs:
//   • DOWNLOAD_TIMEOUT_MS — full request budget for streaming a profile zip.
//     Without this, axios with responseType:"stream" will hang forever if
//     the server stops sending bytes mid-stream.
//   • API_TIMEOUT_MS — small-body JSON calls (e.g. /getversion).
const DOWNLOAD_TIMEOUT_MS = 60_000
const API_TIMEOUT_MS      = 30_000
const basePath = app.isPackaged ? process.resourcesPath : __dirname

// Two ways to run the SOCKS5 relay, in order of preference:
//
//   proxyServer.js  — the SOURCE, run by Electron's own Node (ELECTRON_RUN_AS_NODE).
//                     Preferred, because it is the version that actually gets
//                     edited. Needs no extra runtime: process.execPath IS Electron.
//   proxyServer.exe — a prebuilt ~38 MB bundle with NO build script in this repo.
//                     The committed copy predates per-profile relays: it ignores
//                     --port (always binds 1080) and splits args on every "=",
//                     which truncates any proxy password containing one. Kept only
//                     as a fallback for installs where the .js was not shipped.
let proxyScriptPath = path.join(__dirname, "proxyServer.js")
let proxyPath = path.join(basePath, "chrome", "proxyServer.exe")
let proxyProcContainer = []
const pipe = promisify(pipeline)

/**
 * Stream a file from `url` to `savePath`. Throws on any non-success response —
 * the caller decides how to handle each error class (404 vs network vs 5xx).
 *
 * Retries the INITIAL HTTP request only. Once the stream is established we
 * let the pipeline run because interrupting a half-streamed file and retrying
 * would leave a partial file on disk.
 *
 * Returns true on success. Throws otherwise.
 */
async function downloadFile(url, savePath, token, onProgress) {
  const response = await withNetworkRetry(() =>
    axios.get(url, {
      responseType: "stream",
      headers: { Authorization: "Bearer " + token },
      timeout: DOWNLOAD_TIMEOUT_MS,
      onDownloadProgress: (event) => {},
      // We want to handle 404 ourselves (caller-decides) rather than retry it.
      // axios already considers 4xx as errors; the retry helper skips 4xx.
    })
  )

  const totalLength = response.headers["content-length"]
  let downloaded = 0

  response.data.on("data", (chunk) => {
    downloaded += chunk.length
    if (totalLength) {
      const percent = Math.round((downloaded / totalLength) * 100)
      onProgress(percent)
    }
  })

  await pipe(response.data, fs.createWriteStream(savePath))
  return true
}

// Convenience: did this axios error come back as an HTTP 404?
function is404(err) {
  return err?.response?.status === 404
}

function uniqueString() {
  return Date.now().toString(36) + Math.random().toString(36).slice(2)
}

async function zipFolders(folders, dest) {
  return new Promise((resolve, reject) => {
    const output = fs.createWriteStream(dest)
    const archive = archiver("zip", { zlib: { level: 9 } })

    output.on("close", () => resolve())
    archive.on("error", (err) => reject(err))

    archive.pipe(output)

    // add each folder with its name preserved
    folders.forEach((folder) => {
      const folderName = path.basename(folder)
      archive.directory(folder, folderName)
    })

    archive.finalize()
  })
}

async function uploadFile(url, token, filePath, name, version) {
  try {
    // Rebuild the FormData on each retry attempt — fs.createReadStream
    // is single-use (can't replay a consumed stream), so naively retrying
    // the same `form` object would error on the second attempt with
    // "stream has been consumed". Closing over the builder fixes this.
    const res = await withNetworkRetry(() => {
      const form = new FormData()
      form.append("file", fs.createReadStream(path.join(basePath, filePath)))
      form.append("target", "syncProfile")
      form.append("name", name)
      form.append("profileVersion", version)
      return axios.post(url, form, {
        headers: {
          ...form.getHeaders(),
          // Do NOT set Content-Type manually — form-data + axios will
          // build the multipart boundary themselves. Explicit Content-Type
          // here overwrites that boundary and the server can't parse.
          Authorization: "Bearer " + token,
        },
        maxBodyLength: Infinity,
      })
    })
    console.log(`[uploadFile] POST ${url} → HTTP ${res?.status}${res?.data?.error ? " (server returned error flag)" : " OK"}`)
    return !res?.data?.error
  } catch (error) {
    const status = error?.response?.status
    console.error(`[uploadFile] POST ${url} → FAILED${status ? " HTTP " + status : ""}: ${error.message}`)
    dialog.showErrorBox("Network Error:", error.message || "Carga fallida")
    return false
  }
}

async function wait(s) {
  return new Promise((rs) => {
    setTimeout(() => {
      rs()
    }, s * 1000)
  })
}

async function isProfileUpdateAvailable(profilePath, token, profileUniqueName) {
  const profileCurrentVersionPath = path.join(profilePath, "profileVersion.txt")
  let currentVersion = null
  let res
  try {
    res = await withNetworkRetry(() =>
      axios.post(
        `${API_URL}/getversion`,
        { profileUniqueName },
        {
          headers: { Authorization: `Bearer ${token}` },
          timeout: API_TIMEOUT_MS,
        },
      )
    )
  } catch (e) {
    dialog.showErrorBox("Network Error:", e.message || "No se pudo verificar la versión")
    return false
  }
  const liveVersion = res?.data?.version
  if (fs.existsSync(profileCurrentVersionPath)) {
    currentVersion = fs.readFileSync(profileCurrentVersionPath, "utf-8").trim()
  }
  if (liveVersion != currentVersion) return liveVersion
  return false
}
async function moveFolder(src, dest) {
  await fsx.copy(path.join(basePath, src), path.join(basePath, dest), { overwrite: true })
  await fsx.remove(path.join(basePath, src))
}

// Ask the OS for a guaranteed-free TCP port on the loopback interface, used for
// Chrome's --remote-debugging-port. The old code took a RANDOM server-assigned
// port (40000–60000) with no knowledge of what's free on the CLIENT — which
// could fail to bind (hanging the launch) or, worse, attach the cookie importer
// to a DIFFERENT profile's browser already listening on that port.
function getFreePort() {
  return new Promise((resolve, reject) => {
    const srv = net.createServer()
    srv.unref()
    srv.on("error", reject)
    srv.listen(0, "127.0.0.1", () => {
      const { port } = srv.address()
      srv.close(() => resolve(port))
    })
  })
}

// CDP's Storage.setCookies only accepts the SameSite enum "Strict" | "Lax" |
// "None". Browser-extension cookie exports (Cookie-Editor / EditThisCookie) use
// values like "no_restriction", "unspecified", "lax", "strict" — passing those
// straight through makes CDP reject the cookie, so it gets silently skipped
// (and cross-site auth cookies, the ones that matter, are exactly "no_restriction").
// Normalize here; return undefined for anything we can't map so the cookie is
// set WITHOUT a SameSite and Chrome applies its own default.
function normalizeSameSite(v) {
  switch (String(v ?? "").toLowerCase()) {
    case "no_restriction":
    case "none":
      return "None"
    case "lax":
      return "Lax"
    case "strict":
      return "Strict"
    default:
      return undefined // "unspecified" / blank / unknown
  }
}

// Normalize whatever was pasted/stored into a FLAT array of cookie objects.
// Handles the common shapes so we don't have to care about the exact exporter:
//   • a flat array:                 [ {name,value,domain,...}, ... ]
//   • an array of site wrappers:    [ {origin, cookies:[...]}, ... ]
//   • a single wrapper object:      { origin, cookies:[...] }
// Anything we can't recognise yields [] (caller logs "nothing to import").
function extractCookies(parsed) {
  if (!parsed) return []
  if (Array.isArray(parsed)) {
    const out = []
    for (const item of parsed) {
      if (item && Array.isArray(item.cookies)) out.push(...item.cookies) // wrapper entry
      else if (item && (item.name !== undefined || item.value !== undefined)) out.push(item) // plain cookie
    }
    // If none matched but it was already an array, assume it's a cookie array.
    return out.length ? out : parsed.filter((c) => c && typeof c === "object")
  }
  if (Array.isArray(parsed.cookies)) return parsed.cookies
  return []
}

// Set an array of cookie objects on an ALREADY-CONNECTED puppeteer browser.
// Shared by both importCookies (file → freshly-launched browser) and
// injectCookies (paste → already-running browser). Each cookie is set in
// isolation so one bad entry can't abort the rest. Returns how many succeeded.
async function applyCookies(browser, cookies, logTag = "cookies") {
  let ok = 0
  for (const P of cookies) {
    try {
      const sameSite = normalizeSameSite(P.sameSite)
      await browser.setCookie({
        name: P.name,
        value: P.value,
        domain: P.domain, // must match visited site
        path: P.path || "/",
        // SameSite=None is only valid on a Secure cookie — force it, or CDP
        // rejects the whole cookie. Otherwise honour the exported flag.
        secure: sameSite === "None" ? true : !!P.secure,
        httpOnly: P.httpOnly,
        // Omit SameSite when we can't map it (e.g. "unspecified") so CDP
        // doesn't throw — Chrome then applies its own default.
        ...(sameSite ? { sameSite } : {}),
        // NOTE: P.session / P.storeId are intentionally NOT forwarded — they
        // aren't valid CDP CookieParam fields; "expires" alone controls
        // persistence (absent ⇒ session cookie). "expirationDate" is the
        // Chrome-extension export field; "expires" is the Puppeteer one.
        expires: P.expires ?? P.expirationDate,
      })
      ok++
    } catch (e) {
      console.warn(`[${logTag}] skipped cookie`, P?.name, "→", e.message)
    }
  }
  return ok
}

// After cookies are set, reload every open http(s) tab so the site re-requests
// WITH the new cookies — otherwise the page that loaded pre-injection still
// shows logged-out until the user manually refreshes. Best-effort per page.
async function reloadOpenPages(browser, logTag = "cookies") {
  try {
    const pages = await browser.pages()
    let reloaded = 0
    for (const page of pages) {
      try {
        const url = page.url() || ""
        if (/^https?:/i.test(url)) {
          await page.reload({ waitUntil: "domcontentloaded", timeout: 15000 })
          reloaded++
        }
      } catch (_) {
        /* one tab failing to reload must not block the others */
      }
    }
    if (reloaded) console.log(`[${logTag}] reloaded ${reloaded} tab(s) so the cookies take effect`)
  } catch (_) {
    /* pages() can fail if the browser is mid-shutdown — ignore */
  }
}

// Connect to a RUNNING browser by its debug port and inject cookies LIVE —
// this is the import-while-open flow: open the profile (it binds a debug port),
// then paste cookies and they go straight into the live browser. The page must
// be reloaded afterwards for the site to pick them up. Returns {ok, total}.
async function injectCookies(port, cookies) {
  cookies = extractCookies(cookies)
  if (!cookies.length) {
    console.error(`[injectCookies] no usable cookie objects to inject`)
    return { ok: 0, total: 0 }
  }
  if (!port) {
    console.error("[injectCookies] no debug port for this profile — is the browser actually open?")
    return { ok: 0, total: 0 }
  }
  const browserURL = "http://localhost:" + port
  let browser
  try {
    // defaultViewport:null is CRITICAL — without it puppeteer.connect() forces an
    // 800x600 emulated viewport onto the tab it attaches to, shrinking the page
    // inside the maximized window (and it persists after disconnect). null = use
    // the real window size, leave the viewport untouched.
    browser = await puppeteerCore.connect({ browserURL, defaultViewport: null })
    console.log(`[injectCookies] injecting ${cookies.length} cookies into the running browser on port ${port}…`)
    const ok = await applyCookies(browser, cookies, "injectCookies")
    if (ok === 0) console.error(`[injectCookies] 0/${cookies.length} cookies set — none were accepted (check cookie fields)`)
    else console.log(`[injectCookies] injected ${ok}/${cookies.length} cookies`)
    await reloadOpenPages(browser, "injectCookies")
    return { ok, total: cookies.length }
  } catch (e) {
    console.error(`[injectCookies] could not connect to the running browser on port ${port}:`, e.message)
    return { ok: 0, total: cookies.length }
  } finally {
    // Disconnect right after — leaving a CDP client attached can keep Chrome
    // alive past its last window close and stall the play/pause button.
    try {
      await browser?.disconnect()
    } catch (_) {}
  }
}

async function importCookies(cookiesPath, port) {
  if (!fs.existsSync(cookiesPath)) return
  const browserURL = "http://localhost:" + port
  // Chrome needs a moment after launch before its DevTools endpoint answers —
  // poll /json/version until it does so cookie import doesn't race startup.
  // Bounded poll: if Chrome never exposes its DevTools endpoint (e.g. the port
  // failed to bind), resolve false after a timeout instead of looping forever
  // — an un-bounded poll here used to hang the whole open-browser handler.
  const READY_TIMEOUT_MS = 20000
  const ready = await new Promise((resolve) => {
    const start = Date.now()
    const int = setInterval(async () => {
      try {
        const r = await fetch(browserURL + "/json/version")
        if (r.ok) {
          clearInterval(int)
          return resolve(true)
        }
      } catch (_) {
        // endpoint not up yet — keep polling until the timeout
      }
      if (Date.now() - start > READY_TIMEOUT_MS) {
        clearInterval(int)
        resolve(false)
      }
    }, 200)
  })
  if (!ready) {
    console.error(`[importCookies] DevTools endpoint not reachable on port ${port} within ${READY_TIMEOUT_MS}ms — skipping cookie import`)
    return
  }

  let browser
  try {
    // defaultViewport:null is CRITICAL — without it puppeteer.connect() forces an
    // 800x600 emulated viewport onto the tab it attaches to, shrinking the page
    // inside the maximized window (and it persists after disconnect). null = use
    // the real window size, leave the viewport untouched.
    browser = await puppeteerCore.connect({ browserURL, defaultViewport: null })

    let parsed
    try {
      parsed = JSON.parse(fs.readFileSync(cookiesPath, "utf8"))
    } catch (e) {
      console.error("[importCookies] cookies file missing/malformed:", e.message)
      return
    }
    const cookiesFromFile = extractCookies(parsed)
    if (!cookiesFromFile.length) {
      console.error("[importCookies] no usable cookie objects in the file — nothing to import")
      return
    }
    console.log(`[importCookies] importing ${cookiesFromFile.length} cookies into browser on port ${port}…`)

    const ok = await applyCookies(browser, cookiesFromFile, "importCookies")
    if (ok === 0) console.error(`[importCookies] 0/${cookiesFromFile.length} cookies set — none were accepted (check cookie fields)`)
    else console.log(`[importCookies] imported ${ok}/${cookiesFromFile.length} cookies`)
    await reloadOpenPages(browser, "importCookies")
  } catch (e) {
    // Never throw out of here — the browser has already launched; a CDP error
    // must not break the open-browser handler or the play/pause button.
    console.error(`[importCookies] injection failed on port ${port}: ${e?.message || e}`)
  } finally {
    // Always disconnect — leaving a CDP client attached can keep Chrome alive
    // after its last window closes, which would stop the spawned process's
    // 'exit' event (and the renderer's play/pause button) from firing.
    try {
      await browser?.disconnect()
    } catch (_) {}
  }
}
// ── DevTools guard ────────────────────────────────────────────────────────────
// Watches a spawned profile browser and CLOSES any DevTools window the user
// opens. Uses ONLY stateless HTTP against the CDP endpoint (the same /json the
// cookie importer pokes) — NEVER a persistent puppeteer/CDP client, because a
// held client keeps Chrome alive after its last window closes and would break the
// process 'exit' detection (see importCookies' disconnect note above). A DevTools
// frontend shows up as a target whose url starts with "devtools://" (no normal
// page has that scheme, so there are ZERO false positives). We close it via the
// CDP /json/close/<id> endpoint. Returns a stop() to clear the interval on close.
function watchDevtools(port) {
  const base = "http://127.0.0.1:" + port
  let seenAlive = false
  let missesAfterAlive = 0
  const int = setInterval(async () => {
    let targets
    try {
      const r = await fetch(base + "/json/list")
      if (!r.ok) {
        if (seenAlive && ++missesAfterAlive > 8) clearInterval(int)
        return
      }
      targets = await r.json()
    } catch (_) {
      // Port unreachable: browser still starting (before seenAlive) OR closed
      // (after). Only stop once it was alive and then went away.
      if (seenAlive && ++missesAfterAlive > 8) clearInterval(int)
      return
    }
    seenAlive = true
    missesAfterAlive = 0
    if (!Array.isArray(targets)) return
    // Deliberately silent: this polls every 600ms for the life of the profile, and
    // dumping the target list on every change filled the terminal with DevTools
    // chatter. The only line worth printing is the one below, when it acts.
    for (const t of targets) {
      const u = String(t.url || "")
      if (u.startsWith("devtools://") && t.id) {
        console.warn("[devtools-guard] DevTools opened → closing it:", u)
        try { await fetch(base + "/json/close/" + t.id) } catch (_) {}
      }
    }
  }, 600)
  return () => { try { clearInterval(int) } catch (_) {} }
}
function sha256(text) {
  return crypto.createHash("sha256").update(String(text), "utf8").digest("hex")
}
function createProxyFile(fileName = "background.min.js", data) {
  fs.writeFileSync(fileName, data, "utf8")
  return fileName
}
/**
 * `socks5://user:pass@host:port` or `socks5://host:port:user:pass` -> `socks5://host:port`.
 * Never log credentials.
 *
 * Hand-rolled rather than `new URL()` for the same reason the relay's parser is:
 * the colon form most providers hand out is not a valid URL, so URL() threw and
 * every log line read "(unparseable proxy)" — hiding the host exactly when a
 * proxy problem was being diagnosed.
 */
function redactProxy(proxy) {
  const text = String(proxy || "").trim()
  const scheme = /^([a-z][a-z0-9+.-]*):\/\/(.*)$/i.exec(text)
  const protocol = scheme ? scheme[1].toLowerCase() : "socks5"
  const rest = (scheme ? scheme[2] : text).replace(/\/+$/, "")
  const at = rest.lastIndexOf("@")
  const authority = at === -1 ? rest : rest.slice(at + 1)
  const parts = authority.split(":")
  const host = parts[0] || "(unknown host)"
  const port = parts[1] || "?"
  return `${protocol}://${host}:${port}`
}

/**
 * Starts a local no-auth SOCKS5 relay that forwards to `proxy`, an
 * AUTHENTICATED upstream, injecting the credentials on the way out.
 *
 * This exists because Chrome cannot authenticate a SOCKS proxy: given
 * socks5://user:pass@host:port on --proxy-server it drops the credentials and
 * connects anonymously, which the upstream then refuses. Pointing Chrome at
 * this relay is the only way to give a profile an authed SOCKS5 exit.
 *
 * ONE RELAY PER PROFILE, each on its own `port`. This used to be a single
 * shared relay on 1080 that killed every previous relay on start, which meant
 * opening a second profile silently repointed the first profile's already-open
 * window at the second profile's upstream.
 *
 * Returns the child process so the caller can stop it when that profile's
 * browser closes, or null if it could not be spawned.
 */
function startProxyServer(proxy, port) {
  try {
    const args = [`--proxy=${proxy}`, `--port=${port}`]
    const useScript = fs.existsSync(proxyScriptPath)
    if (!useScript) {
      console.warn(
        `[startProxyServer] ${proxyScriptPath} not found — falling back to the prebuilt ` +
          `proxyServer.exe, which IGNORES --port and will bind 1080 for every profile. ` +
          `Ship proxyServer.js next to util.js to get per-profile relays.`,
      )
    }
    let proc = useScript
      ? spawn(process.execPath, [proxyScriptPath, ...args], { env: { ...process.env, ELECTRON_RUN_AS_NODE: "1" } })
      : spawn(proxyPath, args)
    // A missing/failing proxyServer.exe emits an ASYNC 'error' (ENOENT). Without an
    // 'error' listener that becomes an UNCAUGHT exception that crashes the whole
    // app ("A JavaScript error occurred in the main process"). Handle it so the
    // profile still opens — pointed at a relay port with nothing behind it, so it
    // fails CLOSED rather than falling back to a direct, unproxied connection.
    proc.on("error", (e) => {
      console.error(`[startProxyServer] proxy relay failed to launch (${proxyPath}): ${e?.message || e}`)
    })
    proc.on("exit", (code) => {
      if (code) console.error(`[startProxyServer] relay on port ${port} exited with code ${code}`)
      const i = proxyProcContainer.indexOf(proc)
      if (i > -1) proxyProcContainer.splice(i, 1)
    })
    proxyProcContainer.push(proc)
    console.log(`[startProxyServer] relay 127.0.0.1:${port} -> ${redactProxy(proxy)} (PID ${proc.pid})`)
    return proc
  } catch (e) {
    console.error(`[startProxyServer] spawn threw: ${e?.message || e}`)
    return null
  }
}

/** Stops one relay started by startProxyServer. Safe to call twice. */
function stopProxyServer(proc) {
  if (!proc) return
  const i = proxyProcContainer.indexOf(proc)
  if (i > -1) proxyProcContainer.splice(i, 1)
  try {
    if (proc.pid && proc.exitCode === null) proc.kill()
  } catch (e) {
    console.error(`[stopProxyServer] could not stop relay: ${e?.message || e}`)
  }
}

/** Stops every relay still running — app shutdown, so none are orphaned. */
function stopAllProxyServers() {
  for (const proc of [...proxyProcContainer]) stopProxyServer(proc)
}

module.exports = { importCookies, injectCookies, extractCookies, getFreePort, downloadFile, uniqueString, zipFolders, uploadFile, wait, isProfileUpdateAvailable, moveFolder, sha256, createProxyFile, startProxyServer, stopProxyServer, stopAllProxyServers, is404, watchDevtools }
